style.css:
@-moz-document domain("calendar.google.com") {
/* Targets event titles, dates, headers, and other text */
  [data-eventid], 
  .FC-event, 
  .event-title, 
  .calendar-date-header,
  .mvNeod, 
  .YVSLxb, 
  .Lv2Cte, 
  .iRx8od {
    text-transform: lowercase !important;
    font-variant: normal !important; /* Disables small-caps in headers */
  }
}
